import ch.jalu.configme.exception.ConfigMeException;
import ch.jalu.configme.properties.Property;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import java.util.List;

public class PropertyListBuilderTest {

    @Test
    public void addTest() {
        // Given
        Property<String> property = mock(Property.class);
        when(property.getPath()).thenReturn("test.property");
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();

        // When
        propertyListBuilder.add(property);

        // Then
        Map<String, Object> rootEntries = propertyListBuilder.getRootEntries();
        assertTrue("Root entries should contain added property", rootEntries.containsKey("test.property"));
    }

    @Test(expected = ConfigMeException.class)
    public void addDuplicatePropertyTest() {
        // Given
        Property<String> property = mock(Property.class);
        when(property.getPath()).thenReturn("test.property");
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        propertyListBuilder.add(property);

        // When
        propertyListBuilder.add(property); // Should throw ConfigMeException
    }

    @Test
    public void createTest() {
        // Given
        Property<String> property = mock(Property.class);
        when(property.getPath()).thenReturn("test.property");
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        propertyListBuilder.add(property);

        // When
        List<Property<?>> properties = propertyListBuilder.create();

        // Then
        assertEquals(1, properties.size());
        assertTrue(properties.contains(property));
    }

    @Test
    public void getRootEntriesTest() {
        // Given
        Property<String> property = mock(Property.class);
        when(property.getPath()).thenReturn("test.property");
        PropertyListBuilder propertyListBuilder = new PropertyListBuilder();
        propertyListBuilder.add(property);

        // When
        Map<String, Object> rootEntries = propertyListBuilder.getRootEntries();

        // Then
        assertTrue(rootEntries.containsKey("test.property"));
    }

}
